// Charger density index — record JAH-GPC-GANCHARGER-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"watts": 65, "ports": 2, "price_usd": 40};
var value = (m.watts*m.ports/m.price_usd*10);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPC-GANCHARGER-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPC-GANCHARGER-000001|' + value.toFixed(2) + ' density index');

